create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','admin','member');
create type public.task_status as enum ('todo','in_progress','waiting','done','cancelled');
create type public.task_priority as enum ('low','medium','high','urgent');
create type public.line_status as enum ('unprocessed','task_created','event_created','memo','archived');
create type public.google_sync_status as enum ('not_synced','pending','synced','error');
create table public.communities(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key default gen_random_uuid(),auth_user_id uuid not null unique references auth.users(id) on delete cascade,display_name text not null check(length(display_name)<=100),avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.community_members(id uuid primary key default gen_random_uuid(),community_id uuid not null references public.communities on delete cascade,profile_id uuid not null references public.profiles on delete cascade,role member_role not null default 'member',active boolean not null default true,created_at timestamptz not null default now(),unique(community_id,profile_id));
create table public.events(id uuid primary key default gen_random_uuid(),community_id uuid not null references public.communities on delete cascade,title text not null check(length(title)<=160),description text not null default '',location text not null default '',start_at timestamptz not null,end_at timestamptz,all_day boolean not null default false,google_calendar_event_id text,google_sync_status google_sync_status not null default 'not_synced',created_by uuid references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_at is null or end_at>=start_at));
create table public.event_members(event_id uuid references public.events on delete cascade,member_id uuid references public.community_members on delete cascade,primary key(event_id,member_id));
create table public.tasks(id uuid primary key default gen_random_uuid(),community_id uuid not null references public.communities on delete cascade,title text not null check(length(title)<=160),description text not null default '',status task_status not null default 'todo',priority task_priority not null default 'medium',assignee_id uuid references public.community_members on delete set null,due_date timestamptz,event_id uuid references public.events on delete set null,source_type text not null default 'manual' check(source_type in ('manual','line','event')),source_id uuid,created_by uuid references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),completed_at timestamptz);
create table public.line_groups(id uuid primary key default gen_random_uuid(),community_id uuid not null references public.communities on delete cascade,line_group_id text not null unique,display_name text not null,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.line_users(id uuid primary key default gen_random_uuid(),line_user_id text not null unique,display_name text,member_id uuid references public.community_members on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.line_messages(id uuid primary key default gen_random_uuid(),community_id uuid not null references public.communities on delete cascade,line_group_id uuid references public.line_groups on delete set null,line_user_id uuid references public.line_users on delete set null,line_message_id text not null unique,message_type text not null,text text,status line_status not null default 'unprocessed',received_at timestamptz not null,raw_event jsonb not null,created_at timestamptz not null default now());
create table public.google_connections(id uuid primary key default gen_random_uuid(),community_id uuid not null unique references public.communities on delete cascade,google_email text not null,calendar_id text not null,encrypted_refresh_token text not null,oauth_state_hash text,created_by uuid references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.activity_logs(id uuid primary key default gen_random_uuid(),community_id uuid not null references public.communities on delete cascade,actor_id uuid references public.profiles,action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index tasks_community_status_due_idx on public.tasks(community_id,status,due_date);create index events_community_start_idx on public.events(community_id,start_at);create index line_messages_community_status_idx on public.line_messages(community_id,status,received_at desc);
create function public.is_active_member(cid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from community_members cm join profiles p on p.id=cm.profile_id where cm.community_id=cid and cm.active and p.auth_user_id=auth.uid())$$;
create function public.current_user_community_role(cid uuid) returns member_role language sql stable security definer set search_path=public as $$select cm.role from community_members cm join profiles p on p.id=cm.profile_id where cm.community_id=cid and cm.active and p.auth_user_id=auth.uid() limit 1$$;
alter table communities enable row level security;alter table profiles enable row level security;alter table community_members enable row level security;alter table tasks enable row level security;alter table events enable row level security;alter table event_members enable row level security;alter table line_groups enable row level security;alter table line_users enable row level security;alter table line_messages enable row level security;alter table google_connections enable row level security;alter table activity_logs enable row level security;
create policy community_read on communities for select using(is_active_member(id));create policy profiles_read on profiles for select using(exists(select 1 from community_members cm where cm.profile_id=profiles.id and is_active_member(cm.community_id)));create policy members_read on community_members for select using(is_active_member(community_id));create policy members_owner_write on community_members for all using(current_user_community_role(community_id)='owner') with check(current_user_community_role(community_id)='owner');
create policy tasks_read on tasks for select using(is_active_member(community_id));create policy tasks_insert on tasks for insert with check(is_active_member(community_id));create policy tasks_update on tasks for update using(current_user_community_role(community_id) in ('owner','admin') or created_by=(select id from profiles where auth_user_id=auth.uid()) or assignee_id=(select cm.id from community_members cm join profiles p on p.id=cm.profile_id where p.auth_user_id=auth.uid() and cm.community_id=tasks.community_id));create policy tasks_delete on tasks for delete using(current_user_community_role(community_id) in ('owner','admin'));
create policy events_read on events for select using(is_active_member(community_id));create policy events_write on events for all using(current_user_community_role(community_id) in ('owner','admin')) with check(current_user_community_role(community_id) in ('owner','admin'));create policy inbox_read on line_messages for select using(is_active_member(community_id));create policy inbox_process on line_messages for update using(current_user_community_role(community_id) in ('owner','admin'));create policy groups_read on line_groups for select using(is_active_member(community_id));create policy logs_read on activity_logs for select using(is_active_member(community_id));create policy google_owner on google_connections for all using(current_user_community_role(community_id)='owner') with check(current_user_community_role(community_id)='owner');
